// Получение значения текстовой переменной CT_team_management
var player = GetPlayer();
var textVariable = player.GetVar("CT_critical_thinking");

// Указание позиции символа и нового значения
var position = 0; // Позиция символа, который нужно изменить (0 - первый символ, 1 - второй символ и т.д.)
var newValue = "0"; // Новое значение символа

// Проверка, что указанная позиция существует в строке
if (position >= 0 && position < textVariable.length) {
    // Замена символа на указанной позиции
    textVariable = textVariable.substring(0, position) + newValue + textVariable.substring(position + 1);
} else if (position === textVariable.length) {
    // Если позиция равна длине строки, просто добавляем новый символ в конец
    textVariable += newValue;
} else {
    // Если позиция за пределами текущей длины строки, выводим сообщение об ошибке в консоль
    console.error("Указанная позиция выходит за пределы длины строки.");
}

// Установка обновленного значения в текстовую переменную
player.SetVar("CT_critical_thinking", textVariable);

